mapper.select:
SELECT b.id, b.id_key idKey, b.odd_number oddNumber, b.oper_time operTime, a.material_id materialId, a.norms_id normsId, a.depot_id depotId, a.oper_number operNumber, a.unit_price unitPrice, a.all_price allPrice FROM erp_depotitem a, erp_depothead b
a.parent_id = b.id AND b.state = #{state}
#{subType}
${sqlExtract}
AND b.odd_number like CONCAT('%', #{keyword}, '%')
AND a.tenant_id = #{tenantId} AND b.tenant_id = #{tenantId}
ORDER BY b.oper_time DESC

SELECT q.material_id materialId, q.norms_id normsId, IFNULL(SUM(q.oper_number), 0) currentTock, FORMAT(IFNULL(SUM(p.total_price), 0), 2) currentTockMoney FROM erp_depothead p, erp_depotitem q
q.parent_id = p.id
#{subType}
${sqlExtract}
AND DATE_FORMAT(p.oper_time, '%Y-%m') = #{keyword}
AND p.tenant_id = #{tenantId} AND q.tenant_id = #{tenantId}
GROUP BY q.norms_id

    	SELECT
			a.id,
			a.id_key idKey,
			a.holder_id holderId,
			a.odd_number oddNumber,
			a.total_price totalPrice,
			a.oper_time operTime
		FROM
			erp_depothead a

			a.holder_key = #{holderKey}
			AND a.state = #{state}

				${sqlExtract}


				AND DATE_FORMAT(a.oper_time, '%Y-%m') = #{keyword}


				AND a.tenant_id = #{tenantId}
